select
a.device_id,
a.mete_id,
a.mete_name,
a.up_effect,
a.down_effect,
a.mete_index,
a.mete_cid,
a.signal_kind,
a.last_value,
a.last_time,
a.explain_type,
a.report_type,
a.report_level,
a.mask_type,
a.mask_mid,
a.mask_string,
a.mask_value,
a.delay_time,
a.mete_code,
a.device_type,
a.description,
a.isshield,
a.storageperiod,
a.describer,
a.alarmthresbhold,
a.alarmlevel,
a.link_mete_id
from t_cfg_telesignal a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=VARCHAR}
 and a.mete_id = #{meteId, jdbcType=VARCHAR}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=INTEGER}
 and a.down_effect = #{downEffect, jdbcType=INTEGER}
 and a.mete_index = #{meteIndex, jdbcType=INTEGER}
 and a.mete_cid = #{meteCid, jdbcType=INTEGER}
 and a.signal_kind = #{signalKind, jdbcType=INTEGER}
 and a.last_value = #{lastValue, jdbcType=INTEGER}
 and a.last_time = #{lastTime, jdbcType=TIMESTAMP}
 and a.explain_type = #{explainType, jdbcType=INTEGER}
 and a.report_type = #{reportType, jdbcType=INTEGER}
 and a.report_level = #{reportLevel, jdbcType=INTEGER}
 and a.mask_type = #{maskType, jdbcType=INTEGER}
 and a.mask_mid = #{maskMid, jdbcType=VARCHAR}
 and a.mask_string = #{maskString, jdbcType=VARCHAR}
 and a.mask_value = #{maskValue, jdbcType=INTEGER}
 and a.delay_time = #{delayTime, jdbcType=INTEGER}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.description = #{description, jdbcType=VARCHAR}
 and a.isshield = #{isshield, jdbcType=INTEGER}
 and a.storageperiod = #{storageperiod, jdbcType=BIGINT}
 and a.describer = #{describer, jdbcType=VARCHAR}
 and a.alarmthresbhold = #{alarmthresbhold, jdbcType=INTEGER}
 and a.alarmlevel = #{alarmlevel, jdbcType=INTEGER}
 and a.link_mete_id = #{linkMeteId, jdbcType=VARCHAR}

